-- add_check public.records_chat_conversation:constraint:records_chat_conversation_connection_id_chk: added NOT VALID, then validated
ALTER TABLE public."records_chat_conversation" ADD CONSTRAINT "records_chat_conversation_connection_id_chk" CHECK ((data->>'connectionId') IS NULL OR ((data->>'connectionId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) NOT VALID;
ALTER TABLE public."records_chat_conversation" VALIDATE CONSTRAINT "records_chat_conversation_connection_id_chk";
