ALTER TABLE public."records_chat_conversation" VALIDATE CONSTRAINT "records_chat_conversation_connector_party_name_chk";
-- alter_index public.records_chat_conversation:index:records_chat_conversation_channel_external_key: the index exists with another definition
DROP INDEX public."records_chat_conversation_channel_external_key";
CREATE UNIQUE INDEX "records_chat_conversation_channel_external_key" ON public."records_chat_conversation" USING btree (workspace_id, (data->>'channel'), ((data->>'connectionId')::uuid), (data->>'externalId')) WHERE (data->>'externalId') IS NOT NULL;
