ALTER TABLE public."records_chat_conversation" DROP CONSTRAINT "records_chat_conversation_kind_chk";
-- add_check public.records_chat_message:constraint:records_chat_message_in_reply_to_chk: added NOT VALID, then validated
ALTER TABLE public."records_chat_message" ADD CONSTRAINT "records_chat_message_in_reply_to_chk" CHECK ((data->>'inReplyTo') IS NULL OR ((data->>'inReplyTo') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) NOT VALID;
ALTER TABLE public."records_chat_message" VALIDATE CONSTRAINT "records_chat_message_in_reply_to_chk";
-- add_unique public.records_chat_message:index:records_chat_message_reply_once_key: on workspace_id, data->>'conversationid', data->>'inreplyto' using btree
CREATE UNIQUE INDEX "records_chat_message_reply_once_key" ON public."records_chat_message" USING btree (workspace_id, ((data->>'conversationId')::uuid), ((data->>'inReplyTo')::uuid)) WHERE ((data->>'role') = 'agent' AND ((data->>'inReplyTo')::uuid) IS NOT NULL);
